/// Maps a schedule channel to the thread it dispatches.
pub fn thread_of(ch: u32) -> Option<Thread> {
  match ch {
    inspect::channels::temp_sensor_temp_sensor_MON => Some(Thread::temp_sensor_temp_sensor),
    inspect::channels::operator_interface_operator_interface_MON => Some(Thread::operator_interface_operator_interface),
    inspect::channels::thermostat_thermostat_MON => Some(Thread::thermostat_thermostat),
    inspect::channels::heat_source_heat_source_MON => Some(Thread::heat_source_heat_source),
    _ => None,
  }
}

fn thread_named(name: &str) -> Option<Thread> {
  match name {
    "temp_sensor_temp_sensor" => Some(Thread::temp_sensor_temp_sensor),
    "operator_interface_operator_interface" => Some(Thread::operator_interface_operator_interface),
    "thermostat_thermostat" => Some(Thread::thermostat_thermostat),
    "heat_source_heat_source" => Some(Thread::heat_source_heat_source),
    _ => None,
  }
}

// ---------------------------------------------------------------------------------
// Reading
// ---------------------------------------------------------------------------------

/// Logical time: advanced whenever a value for the system layer is taken, so each
/// composition can tell what arrived in its own current frame.
static mut NOW: u32 = 0;

fn tick() -> u32 {
  unsafe {
    NOW = NOW.wrapping_add(1);
    NOW
  }
}

/// Each composition's frame start: the time its marking last reached END (or a frame was
/// started for all, see roll_frame).  A value taken after it is in its current frame.
static mut COMP_START: [u32; 1] = [0; 1];


/// A value for the system layer, with the time it was taken; `injected` if a test put it.
#[derive(Clone)]
struct Stamped<T: Clone> {
  at: u32,
  value: Option<T>,
  injected: bool,
}

#[allow(dead_code)]
impl<T: Clone> Stamped<T> {
  const fn empty() -> Self {
    Stamped { at: 0, value: None, injected: false }
  }

  /// The value, if it was taken in the frame that started at `start` (wrap-safe).
  fn visible(&self, start: u32) -> Option<T> {
    if (self.at.wrapping_sub(start) as i32) > 0 { self.value.clone() } else { None }
  }
}

/// Reads ports and state variables for the checks.  Data ports and state variables keep
/// the last value read -- what a thread sees -- so a check reads them as often as it
/// likes.  A data port never written reads as its default, as it does to the thread; a
/// state variable never written makes the check skip (`missing`).  Event ports are
/// read through one cursor per reading thread, so an event is seen once, at the check
/// of the thread that consumes it, however often that check reads it; the system layer
/// reads them as per-frame values (Stamped), for the composition in focus.
pub struct ControllerView {
  focus: Option<Thread>,
  missing: bool,
  /// the frame start of the composition whose assertion is reading
  sys_start: u32,
  pending_thermostat_thermostat_sv_currentSetPoints: Option<Isolette_Data_Model::Set_Points>,
  pending_thermostat_thermostat_sv_lastCmd: Option<Isolette_Data_Model::On_Off>,
  pending_heat_source_heat_source_sv_heater_state: Option<Isolette_Data_Model::On_Off>,
  frame_temp_sensor_temp_sensor_temp_changed: Stamped<u8>,
  frame_operator_interface_operator_interface_desired_temp: Stamped<Isolette_Data_Model::Set_Points>,
  frame_thermostat_thermostat_heat_control: Stamped<Isolette_Data_Model::On_Off>,
  recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat: Option<Isolette_Data_Model::Temp>,
  saved_recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat: Option<Isolette_Data_Model::Temp>,
  recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat: Stamped<u8>,
  saved_recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat: Stamped<u8>,
  seen_temp_sensor_temp_sensor_temp_changed: Option<(bool, u8)>,
  last_temp_sensor_temp_sensor_current_temp: Option<Isolette_Data_Model::Temp>,
  seen_operator_interface_operator_interface_desired_temp: Option<(bool, Isolette_Data_Model::Set_Points)>,
  last_thermostat_thermostat_sv_currentSetPoints: Option<Isolette_Data_Model::Set_Points>,
  last_thermostat_thermostat_sv_lastCmd: Option<Isolette_Data_Model::On_Off>,
  seen_thermostat_thermostat_heat_control: Option<(bool, Isolette_Data_Model::On_Off)>,
  last_heat_source_heat_source_sv_heater_state: Option<Isolette_Data_Model::On_Off>,
}

impl ControllerView {
  pub const fn new() -> Self {
    ControllerView {
      focus: None,
      missing: false,
      sys_start: 0,
      pending_thermostat_thermostat_sv_currentSetPoints: None,
      pending_thermostat_thermostat_sv_lastCmd: None,
      pending_heat_source_heat_source_sv_heater_state: None,
      frame_temp_sensor_temp_sensor_temp_changed: Stamped::empty(),
      frame_operator_interface_operator_interface_desired_temp: Stamped::empty(),
      frame_thermostat_thermostat_heat_control: Stamped::empty(),
      recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat: None,
      saved_recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat: None,
      recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat: Stamped::empty(),
      saved_recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat: Stamped::empty(),
      seen_temp_sensor_temp_sensor_temp_changed: None,
      last_temp_sensor_temp_sensor_current_temp: None,
      seen_operator_interface_operator_interface_desired_temp: None,
      last_thermostat_thermostat_sv_currentSetPoints: None,
      last_thermostat_thermostat_sv_lastCmd: None,
      seen_thermostat_thermostat_heat_control: None,
      last_heat_source_heat_source_sv_heater_state: None,
    }
  }

  /// `t` has completed a dispatch: what it sent on each of its event ports, and what
  /// it received on each unconnected event input, if anything, is this frame's value
  /// for the system assertions.
  fn producer_completed(&mut self, t: Thread) {
    match t {
      Thread::temp_sensor_temp_sensor => {
        {
          let mut v: u8 = Default::default();
          // what it sent last, if it sent more than once (a queue deeper than 1)
          let mut got = false;
          while unsafe { test_obs_get_temp_sensor_temp_sensor_temp_changed__sys(&mut v) } {
            got = true;
          }
          if got {
            self.frame_temp_sensor_temp_sensor_temp_changed = Stamped { at: tick(), value: Some(v), injected: false };
          } else if !self.frame_temp_sensor_temp_sensor_temp_changed.injected {
            // sent nothing: the port carries nothing now -- unless a test injected into it,
            // which its consumers still receive (an injection from an earlier frame is
            // outside the current one by its time anyway)
            self.frame_temp_sensor_temp_sensor_temp_changed = Stamped { at: tick(), value: None, injected: false };
          }
        }
      }
      Thread::operator_interface_operator_interface => {
        {
          let mut v: Isolette_Data_Model::Set_Points = Default::default();
          // what it sent last, if it sent more than once (a queue deeper than 1)
          let mut got = false;
          while unsafe { test_obs_get_operator_interface_operator_interface_desired_temp__sys(&mut v) } {
            got = true;
          }
          if got {
            self.frame_operator_interface_operator_interface_desired_temp = Stamped { at: tick(), value: Some(v), injected: false };
          } else if !self.frame_operator_interface_operator_interface_desired_temp.injected {
            // sent nothing: the port carries nothing now -- unless a test injected into it,
            // which its consumers still receive (an injection from an earlier frame is
            // outside the current one by its time anyway)
            self.frame_operator_interface_operator_interface_desired_temp = Stamped { at: tick(), value: None, injected: false };
          }
        }
      }
      Thread::thermostat_thermostat => {
        {
          let mut v: Isolette_Data_Model::On_Off = Default::default();
          // what it sent last, if it sent more than once (a queue deeper than 1)
          let mut got = false;
          while unsafe { test_obs_get_thermostat_thermostat_heat_control__sys(&mut v) } {
            got = true;
          }
          if got {
            self.frame_thermostat_thermostat_heat_control = Stamped { at: tick(), value: Some(v), injected: false };
          } else if !self.frame_thermostat_thermostat_heat_control.injected {
            // sent nothing: the port carries nothing now -- unless a test injected into it,
            // which its consumers still receive (an injection from an earlier frame is
            // outside the current one by its time anyway)
            self.frame_thermostat_thermostat_heat_control = Stamped { at: tick(), value: None, injected: false };
          }
        }
      }
      _ => {}
    }
  }

  /// `t` overran: skip every event its unobserved dispatch consumed or sent.
  fn drain_cursors(&mut self, t: Thread) {
    match t {
      Thread::temp_sensor_temp_sensor => {
        {
          let mut v: u8 = Default::default();
          while unsafe { test_obs_get_temp_sensor_temp_sensor_temp_changed__temp_sensor_temp_sensor(&mut v) } {}
        }
        {
          let mut v: u8 = Default::default();
          while unsafe { test_obs_get_temp_sensor_temp_sensor_temp_changed__sys(&mut v) } {}
        }
      }
      Thread::thermostat_thermostat => {
        {
          let mut v: u8 = Default::default();
          while unsafe { test_obs_get_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat(&mut v) } {}
        }
        {
          let mut v: Isolette_Data_Model::Set_Points = Default::default();
          while unsafe { test_obs_get_operator_interface_operator_interface_desired_temp__thermostat_thermostat(&mut v) } {}
        }
        {
          let mut v: Isolette_Data_Model::On_Off = Default::default();
          while unsafe { test_obs_get_thermostat_thermostat_heat_control__thermostat_thermostat(&mut v) } {}
        }
        {
          let mut v: Isolette_Data_Model::On_Off = Default::default();
          while unsafe { test_obs_get_thermostat_thermostat_heat_control__sys(&mut v) } {}
        }
      }
      Thread::operator_interface_operator_interface => {
        {
          let mut v: Isolette_Data_Model::Set_Points = Default::default();
          while unsafe { test_obs_get_operator_interface_operator_interface_desired_temp__operator_interface_operator_interface(&mut v) } {}
        }
        {
          let mut v: Isolette_Data_Model::Set_Points = Default::default();
          while unsafe { test_obs_get_operator_interface_operator_interface_desired_temp__sys(&mut v) } {}
        }
      }
      Thread::heat_source_heat_source => {
        {
          let mut v: Isolette_Data_Model::On_Off = Default::default();
          while unsafe { test_obs_get_thermostat_thermostat_heat_control__heat_source_heat_source(&mut v) } {}
        }
      }
    }
  }

  /// `t` is about to be checked for dispatch: remember where the cursors read on its
  /// behalf stand, and what it last received on each aliased input, so a rejected
  /// dispatch can put them back (`rewind_cursors`).
  fn mark_cursors(&mut self, t: Thread) {
    match t {
      Thread::thermostat_thermostat => {
        unsafe { test_obs_mark_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat() };
        unsafe { test_obs_mark_operator_interface_operator_interface_desired_temp__thermostat_thermostat() };
        self.saved_recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat = self.recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat.clone();
        self.saved_recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat = self.recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat.clone();
      }
      Thread::heat_source_heat_source => {
        unsafe { test_obs_mark_thermostat_thermostat_heat_control__heat_source_heat_source() };
      }
      _ => {}
    }
  }

  /// `t`'s dispatch was rejected (D36): it consumed nothing, so neither have its checks,
  /// and it received nothing a composition could see.
  fn rewind_cursors(&mut self, t: Thread) {
    match t {
      Thread::thermostat_thermostat => {
        unsafe { test_obs_rewind_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat() };
        unsafe { test_obs_rewind_operator_interface_operator_interface_desired_temp__thermostat_thermostat() };
        self.recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat = self.saved_recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat.clone();
        self.recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat = self.saved_recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat.clone();
      }
      Thread::heat_source_heat_source => {
        unsafe { test_obs_rewind_thermostat_thermostat_heat_control__heat_source_heat_source() };
      }
      _ => {}
    }
  }

  /// `t` is about to be dispatched: latch what it receives on each connected input a
  /// composition aliases (see ContractObserverPlugin.ReceivedGetter).
  fn latch_received(&mut self, t: Thread) {
    match t {
      Thread::thermostat_thermostat => {
        self.recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat = Some(self.get_temp_sensor_temp_sensor_current_temp());
        {
          let mut v: u8 = Default::default();
          let got = unsafe { test_obs_get_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat(&mut v) };
          self.recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat = Stamped { at: tick(), value: if got { Some(v) } else { None }, injected: false };
        }
      }
      _ => {}
    }
  }

  /// A new frame for every composition, starting at logical time `at`: nothing taken
  /// before it is in the frame.
  fn new_frame_at(&mut self, at: u32) {
    unsafe {
      for start in (&mut *addr_of_mut!(COMP_START)).iter_mut() {
        *start = at;
      }
    }
  }

  /// `t` has dispatched: it adopted any injected state variables, and its sv_ regions
  /// carry them from here on.
  fn clear_pending(&mut self, t: Thread) {
    match t {
      Thread::thermostat_thermostat => {
        self.pending_thermostat_thermostat_sv_currentSetPoints = None;
        self.pending_thermostat_thermostat_sv_lastCmd = None;
      }
      Thread::heat_source_heat_source => {
        self.pending_heat_source_heat_source_sv_heater_state = None;
      }
      _ => {}
    }
  }
}

impl SystemView for ControllerView {
  fn focus(&mut self, t: Option<Thread>) {
    self.focus = t;
    self.missing = false;
    self.seen_temp_sensor_temp_sensor_temp_changed = None;
    self.seen_operator_interface_operator_interface_desired_temp = None;
    self.seen_thermostat_thermostat_heat_control = None;
  }

  fn missing(&self) -> bool {
    self.missing
  }

  fn focus_system(&mut self, composition: usize) {
    self.sys_start = unsafe { COMP_START[composition] };
  }

  fn frame_ended(&mut self, composition: usize) {
    unsafe { COMP_START[composition] = NOW; }
  }

  fn get_recv_thermostat_thermostat_current_temp(&mut self) -> Isolette_Data_Model::Temp {
    match &self.recv_temp_sensor_temp_sensor_current_temp__thermostat_thermostat {
      Some(v) => v.clone(),
      None => Default::default(),
    }
  }

  fn get_recv_thermostat_thermostat_temp_changed(&mut self) -> Option<u8> {
    self.recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat.visible(self.sys_start)
  }

  fn get_temp_sensor_temp_sensor_temp_changed(&mut self) -> Option<u8> {
    let (got, v) = match &self.seen_temp_sensor_temp_sensor_temp_changed {
      Some((got, v)) => (*got, v.clone()),
      None => {
        let mut v: u8 = Default::default();
        let got = unsafe {
          match self.focus {
            Some(Thread::temp_sensor_temp_sensor) => {
              let mut got = false;
              while test_obs_get_temp_sensor_temp_sensor_temp_changed__temp_sensor_temp_sensor(&mut v) {
                got = true;
              }
              got
            }
            Some(Thread::thermostat_thermostat) => match &self.recv_temp_sensor_temp_sensor_temp_changed__thermostat_thermostat.value {
              Some(x) => {
                v = x.clone();
                true
              }
              None => false,
            },
            _ => match self.frame_temp_sensor_temp_sensor_temp_changed.visible(self.sys_start) {
              Some(x) => {
                v = x;
                true
              }
              None => false,
            },
          }
        };
        self.seen_temp_sensor_temp_sensor_temp_changed = Some((got, v.clone()));
        (got, v)
      }
    };
    if got { Some(v) } else { None }
  }

  fn get_temp_sensor_temp_sensor_current_temp(&mut self) -> Isolette_Data_Model::Temp {
    let mut v: Isolette_Data_Model::Temp = Default::default();
    if unsafe { test_obs_get_temp_sensor_temp_sensor_current_temp(&mut v) } {
      self.last_temp_sensor_temp_sensor_current_temp = Some(v);
    }
    match &self.last_temp_sensor_temp_sensor_current_temp {
      Some(v) => v.clone(),
      None => Default::default(),
    }
  }

  fn get_operator_interface_operator_interface_desired_temp(&mut self) -> Option<Isolette_Data_Model::Set_Points> {
    let (got, v) = match &self.seen_operator_interface_operator_interface_desired_temp {
      Some((got, v)) => (*got, v.clone()),
      None => {
        let mut v: Isolette_Data_Model::Set_Points = Default::default();
        let got = unsafe {
          match self.focus {
            Some(Thread::operator_interface_operator_interface) => {
              let mut got = false;
              while test_obs_get_operator_interface_operator_interface_desired_temp__operator_interface_operator_interface(&mut v) {
                got = true;
              }
              got
            }
            Some(Thread::thermostat_thermostat) => test_obs_get_operator_interface_operator_interface_desired_temp__thermostat_thermostat(&mut v),
            _ => match self.frame_operator_interface_operator_interface_desired_temp.visible(self.sys_start) {
              Some(x) => {
                v = x;
                true
              }
              None => false,
            },
          }
        };
        self.seen_operator_interface_operator_interface_desired_temp = Some((got, v.clone()));
        (got, v)
      }
    };
    if got { Some(v) } else { None }
  }

  fn get_thermostat_thermostat_sv_currentSetPoints(&mut self) -> Isolette_Data_Model::Set_Points {
    if self.focus == Some(Thread::thermostat_thermostat) {
      if let Some(v) = &self.pending_thermostat_thermostat_sv_currentSetPoints {
        return v.clone();
      }
    }
    let mut v: Isolette_Data_Model::Set_Points = Default::default();
    if unsafe { test_obs_get_thermostat_thermostat_sv_currentSetPoints(&mut v) } {
      self.last_thermostat_thermostat_sv_currentSetPoints = Some(v);
    }
    match &self.last_thermostat_thermostat_sv_currentSetPoints {
      Some(v) => v.clone(),
      None => {
        self.missing = true;
        Default::default()
      }
    }
  }

  fn get_thermostat_thermostat_sv_lastCmd(&mut self) -> Isolette_Data_Model::On_Off {
    if self.focus == Some(Thread::thermostat_thermostat) {
      if let Some(v) = &self.pending_thermostat_thermostat_sv_lastCmd {
        return v.clone();
      }
    }
    let mut v: Isolette_Data_Model::On_Off = Default::default();
    if unsafe { test_obs_get_thermostat_thermostat_sv_lastCmd(&mut v) } {
      self.last_thermostat_thermostat_sv_lastCmd = Some(v);
    }
    match &self.last_thermostat_thermostat_sv_lastCmd {
      Some(v) => v.clone(),
      None => {
        self.missing = true;
        Default::default()
      }
    }
  }

  fn get_thermostat_thermostat_heat_control(&mut self) -> Option<Isolette_Data_Model::On_Off> {
    let (got, v) = match &self.seen_thermostat_thermostat_heat_control {
      Some((got, v)) => (*got, v.clone()),
      None => {
        let mut v: Isolette_Data_Model::On_Off = Default::default();
        let got = unsafe {
          match self.focus {
            Some(Thread::thermostat_thermostat) => {
              let mut got = false;
              while test_obs_get_thermostat_thermostat_heat_control__thermostat_thermostat(&mut v) {
                got = true;
              }
              got
            }
            Some(Thread::heat_source_heat_source) => test_obs_get_thermostat_thermostat_heat_control__heat_source_heat_source(&mut v),
            _ => match self.frame_thermostat_thermostat_heat_control.visible(self.sys_start) {
              Some(x) => {
                v = x;
                true
              }
              None => false,
            },
          }
        };
        self.seen_thermostat_thermostat_heat_control = Some((got, v.clone()));
        (got, v)
      }
    };
    if got { Some(v) } else { None }
  }

  fn get_heat_source_heat_source_sv_heater_state(&mut self) -> Isolette_Data_Model::On_Off {
    if self.focus == Some(Thread::heat_source_heat_source) {
      if let Some(v) = &self.pending_heat_source_heat_source_sv_heater_state {
        return v.clone();
      }
    }
    let mut v: Isolette_Data_Model::On_Off = Default::default();
    if unsafe { test_obs_get_heat_source_heat_source_sv_heater_state(&mut v) } {
      self.last_heat_source_heat_source_sv_heater_state = Some(v);
    }
    match &self.last_heat_source_heat_source_sv_heater_state {
      Some(v) => v.clone(),
      None => {
        self.missing = true;
        Default::default()
      }
    }
  }
}

